    sante:{s:"Pas encore de position connue.",d:[]}, edu:{s:"Pas encore de position connue.",d:[]}, secu:{s:"Pas encore de position connue.",d:[]}, immi:{s:"Pas encore de position connue.",d:[]}, ecolo:{s:"Pas encore de position connue.",d:[]}, europe:{s:"Pas encore de position connue.",d:[]},
